            while queue:
                vertex = queue.popleft()
                for neighbor in sorted(adjacency[vertex]):
                    if colors[neighbor] == colors[vertex]:
                        colors[neighbor] += 1
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)
