def validate_pkcs7_padding_workload(workload: dict) -> None:
    """Pin the PKCS#7 workload metadata and explicit pointer-boundary fixtures."""
    input_spec = workload.get("input", {})
    output_spec = workload.get("output", {})
    measurement = workload.get("measurement", {})
    expected_source = {
        "repository": "TheAlgorithms/C-Sharp",
        "commit": "96e2905cab7bc6b33ac0a34ee5bb82ddccbcbb6c",
        "path": "Algorithms/Crypto/Paddings/Pkcs7Padding.cs",
        "symbol": "Pkcs7Padding",
        "url": "https://github.com/TheAlgorithms/C-Sharp/blob/96e2905cab7bc6b33ac0a34ee5bb82ddccbcbb6c/Algorithms/Crypto/Paddings/Pkcs7Padding.cs",
    }
    expected_details = (
        "AddPadding validates input_offset, derives the padding count from the full data array length, "
        "then writes at that offset. RemovePadding requires block alignment and count <= block_size. "
        "GetPaddingCount ignores input_offset and validates only a nonempty matching suffix and count <= "
        "data length; it accepts nonaligned lengths and counts above block_size, using the source full-buffer "
        "masked bitwise scan."
    )
    cases = workload.get("cases")
    ids = [case.get("id") for case in cases] if isinstance(cases, list) else []
    if (workload.get("schema_version") != 1
            or workload.get("id") != "thealgorithms-csharp-pkcs7-padding-i64-array-bytes-output-v1"
            or workload.get("algorithm") != "pkcs7_padding"
            or workload.get("function_symbol") != "pkcs7_padding"
            or workload.get("pinned_source") != expected_source
            or input_spec.get("kind") != "packed_signed_64_bit_integer_array"
            or input_spec.get("encoding") != "[operation, block_size, input_offset, data_length, byte_values...]"
            or input_spec.get("operation_values") != {"0": "AddPadding", "1": "RemovePadding", "2": "GetPaddingCount"}
            or input_spec.get("block_size_range") != [1, 16]
            or input_spec.get("data_length_range") != [1, 64]
            or input_spec.get("byte_value_range") != [0, 255]
            or input_spec.get("maximum_length") != MAX_PKCS7_PADDING_INPUT_LENGTH
            or input_spec.get("maximum_parseable_length") != MAX_PKCS7_PADDING_PARSEABLE_INPUT_LENGTH
            or input_spec.get("maximum_valid_input_values") != MAX_PKCS7_PADDING_INPUT_LENGTH
            or input_spec.get("invalid_input_result") != PKCS7_PADDING_INVALID_RESULT
            or input_spec.get("null_input_result") != PKCS7_PADDING_INVALID_RESULT
            or input_spec.get("details") != expected_details
            or output_spec.get("kind") != "byte_sequence"
            or output_spec.get("encoding") != "AddPadding: [padding_count, mutated_data...]; RemovePadding: unpadded prefix; GetPaddingCount: [padding_count]"
            or output_spec.get("result") != "number of returned bytes"
            or output_spec.get("invalid_input_result") != PKCS7_PADDING_INVALID_RESULT
            or output_spec.get("null_output_result") != PKCS7_PADDING_OUTPUT_ERROR_RESULT
            or output_spec.get("insufficient_capacity_result") != PKCS7_PADDING_OUTPUT_ERROR_RESULT
            or output_spec.get("no_write_on_error") is not True
            or output_spec.get("maximum_output_bytes") != PKCS7_PADDING_MAX_OUTPUT_BYTES
            or workload.get("workspace") != {
                "bytes": PKCS7_PADDING_MAX_OUTPUT_BYTES,
                "reason": "The largest output is a one-byte count followed by the 64-byte mutated input.",
            }
            or measurement.get("comparison_model") != "i64_array_bytes_output_call"
            or measurement.get("sample_count") != 5
            or measurement.get("warmup_rounds") != 1
            or measurement.get("repetitions_per_sample") != 100
            or len(ids) != len(PKCS7_PADDING_CASE_IDS)
            or set(ids) != PKCS7_PADDING_CASE_IDS):
        raise ValueError("pkcs7_padding workload metadata does not match its reviewed contract")
    null_inputs = [case for case in cases if case.get("input_is_null") is True]
    null_outputs = [case for case in cases if case.get("output_is_null") is True]
    if (len(null_inputs) != 1 or null_inputs[0].get("id") != "null_input"
            or null_inputs[0].get("input_values") != [] or null_inputs[0].get("input_length") != 4
            or null_inputs[0].get("expected_result") != PKCS7_PADDING_INVALID_RESULT
            or len(null_outputs) != 1 or null_outputs[0].get("id") != "valid_operation_null_output"
            or null_outputs[0].get("expected_result") != PKCS7_PADDING_OUTPUT_ERROR_RESULT
            or any(type(case.get("input_is_null", False)) is not bool
                   or type(case.get("output_is_null", False)) is not bool
                   or type(case.get("output_capacity")) is not int
                   or not 0 <= case["output_capacity"] <= PKCS7_PADDING_MAX_OUTPUT_BYTES
                   for case in cases)):
        raise ValueError("pkcs7_padding workload must cover its null input/output contract")
    for case in cases:
        values = case.get("input_values")
        input_length = case.get("input_length")
        if (not isinstance(values, list)
                or type(input_length) is not int
                or (case.get("input_is_null") is True
                    and (values or not 1 <= input_length <= MAX_PKCS7_PADDING_PARSEABLE_INPUT_LENGTH))
                or (case.get("input_is_null") is not True
                    and input_length != len(values))):
            raise ValueError(f"pkcs7_padding input framing is invalid for {case.get('id')}")


