    case_list = workload.get("cases")
    if not isinstance(case_list, list):
        case_list = []
    case_ids = [case.get("id") for case in case_list if isinstance(case, dict)]
    if (workload.get("schema_version") != 1
            or workload.get("id") != "thealgorithms-lua-linked-stack-nil-i64-operation-trace-v1"
            or workload.get("algorithm") != "linked_stack"
            or workload.get("function_symbol") != "linked_stack"
            or workload.get("pinned_source") != source
            or workload.get("input") != input_spec
            or workload.get("output") != output_spec
            or workload.get("workspace") != {
                "bytes": LINKED_STACK_MAX_OUTPUT_BYTES,
                "meaning": "Maximum output for 64 operation records.",
            }
            or workload.get("measurement") != measurement
            or LINKED_STACK_MAX_OPERATIONS != 64
            or LINKED_STACK_MAX_INPUT_LENGTH != 129
            or LINKED_STACK_MAX_OUTPUT_BYTES != 1536
            or LINKED_STACK_INVALID_RESULT != -1
            or LINKED_STACK_OUTPUT_ERROR != -2
            or len(case_ids) != len(LINKED_STACK_CASE_IDS)
            or len(case_ids) != len(set(case_ids))
            or set(case_ids) != LINKED_STACK_CASE_IDS):
        raise ValueError("linked_stack workload metadata does not match its reviewed contract")

    readme = (ROOT / "benchmarks" / "l" / "linked_stack" / "README.md").read_text(
        encoding="utf-8")
    if source["url"] not in readme:
        raise ValueError("linked_stack README is missing its pinned source link")
    cases = {case["id"]: case for case in case_list}
    maximum_case = cases["maximum_push_count"]
    null_input_case = cases["null_input_positive_length"]
    invalid_null_case = cases["invalid_precedes_null_output"]
    null_output_case = cases["null_output_for_empty_trace"]
    if (len(maximum_case.get("input_values", [])) != LINKED_STACK_MAX_INPUT_LENGTH
            or maximum_case.get("input_length") != LINKED_STACK_MAX_INPUT_LENGTH
            or maximum_case.get("expected_result") != LINKED_STACK_MAX_OUTPUT_BYTES
            or len(bytes.fromhex(maximum_case.get("expected_output_hex", "")))
                != LINKED_STACK_MAX_OUTPUT_BYTES
            or cases["short_output_capacity"].get("output_capacity")
                != LINKED_STACK_MAX_OUTPUT_BYTES - 1
            or cases["short_output_capacity"].get("expected_result") != LINKED_STACK_OUTPUT_ERROR
            or cases["exact_output_capacity"].get("output_capacity") != 24
            or cases["exact_output_capacity"].get("expected_result") != 24
            or null_input_case.get("input_is_null") is not True
            or null_input_case.get("input_values") != []
            or null_input_case.get("input_length") != 1
            or null_input_case.get("expected_result") != LINKED_STACK_INVALID_RESULT
            or invalid_null_case.get("output_is_null") is not True
            or invalid_null_case.get("expected_result") != LINKED_STACK_INVALID_RESULT
            or null_output_case.get("output_is_null") is not True
            or null_output_case.get("expected_result") != LINKED_STACK_OUTPUT_ERROR):
        raise ValueError("linked_stack workload is missing maximum, null, or capacity coverage")

    for case in case_list:
        values = case.get("input_values")
        input_is_null = case.get("input_is_null", False)
        input_length = case.get("input_length", len(values) if isinstance(values, list) else -1)
        output_is_null = case.get("output_is_null", False)
        capacity = case.get("output_capacity", LINKED_STACK_MAX_OUTPUT_BYTES)
        expected_hex = case.get("expected_output_hex", "")
        if (not isinstance(values, list)
                or len(values) > LINKED_STACK_MAX_INPUT_LENGTH
                or any(type(value) is not int or not -(1 << 63) <= value < (1 << 63)
                       for value in values)
                or type(input_is_null) is not bool
                or type(input_length) is not int
                or type(output_is_null) is not bool
                or type(capacity) is not int or not 0 <= capacity <= MAX_OUTPUT_CAPACITY
                or type(expected_hex) is not str
                or (input_is_null and (values or not 1 <= input_length <= LINKED_STACK_MAX_INPUT_LENGTH
                                       or output_is_null))
                or (not input_is_null and input_length != len(values))):
            raise ValueError(f"linked_stack input/output framing is invalid for {case.get('id')}")
        result, output = linked_stack_expected_output(
            values, capacity, output_is_null, input_is_null, input_length)
        if (type(case.get("expected_result")) is not int
                or result != case.get("expected_result")
                or output.hex() != expected_hex.lower()
                or len(output) > LINKED_STACK_MAX_OUTPUT_BYTES
                or (result >= 0 and (result != len(output) or result % 24 != 0))
                or (result < 0 and (result not in (LINKED_STACK_INVALID_RESULT,
                                                   LINKED_STACK_OUTPUT_ERROR) or output))):
            raise ValueError(f"linked_stack workload mismatch: {case.get('id')}")


